#!/usr/bin/env python3
"""Fetch order pages / customer records from the local order service.

Usage:
    fetch.py orders    <outdir>
    fetch.py customers <outdir> <idfile>

Every response is logged to <outdir>/requests.jsonl. Successful bodies are saved
verbatim under <outdir>/pages or <outdir>/customers. Failed requests are retried;
nothing is ever skipped or guessed - the script aborts loudly instead.
"""
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.request
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
MAX_FAILED_ATTEMPTS = 40        # non-rate-limit failures per request before aborting
MAX_RATE_LIMITED = 400          # 429s per request before aborting
MIN_INTERVAL = 0.35             # gentle pacing between requests (seconds)


class Fatal(Exception):
    pass


class Client:
    def __init__(self, outdir):
        os.makedirs(outdir, exist_ok=True)
        self.log = open(os.path.join(outdir, "requests.jsonl"), "a")
        self.token = None
        self.token_born = None
        self.token_uses = 0
        self.last_sent = 0.0
        self.counts = {}

    def note(self, **kw):
        kw["t"] = round(time.time(), 3)
        self.log.write(json.dumps(kw) + "\n")
        self.log.flush()

    def bump(self, key):
        self.counts[key] = self.counts.get(key, 0) + 1

    def _send(self, method, path, auth):
        gap = time.time() - self.last_sent
        if gap < MIN_INTERVAL:
            time.sleep(MIN_INTERVAL - gap)
        self.last_sent = time.time()
        headers = {"Accept": "application/json"}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        req = urllib.request.Request(BASE + path, method=method, headers=headers,
                                     data=b"" if method == "POST" else None)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()

    @staticmethod
    def _wait_hint(headers, data):
        """Largest wait the server asked for (header or body), in seconds, or None."""
        waits = []
        ra = headers.get("Retry-After") if headers is not None else None
        if ra is not None:
            try:
                waits.append(float(ra))
            except ValueError:
                try:
                    waits.append(parsedate_to_datetime(ra).timestamp() - time.time())
                except (TypeError, ValueError):
                    pass
        if isinstance(data, dict):
            v = data.get("retry_after")
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                waits.append(float(v))
        return max(waits) if waits else None

    def refresh_token(self, reason):
        data = self.request("POST", "/token", auth=False,
                            validate=lambda d: None if isinstance(d.get("token"), str) and d["token"]
                            else "no token in body")
        old = (self.token, self.token_uses, None if self.token_born is None
               else round(time.time() - self.token_born, 1))
        self.token = data["token"]
        self.token_born = time.time()
        self.token_uses = 0
        self.bump("token_refresh")
        self.note(event="new_token", token=self.token, reason=reason,
                  old_token=old[0], old_uses=old[1], old_age_s=old[2])

    def request(self, method, path, auth=True, validate=None, not_found_ok=False):
        """Return parsed JSON of a validated 200 response.

        If not_found_ok, a 404 seen on 3 separate attempts returns None.
        """
        failed = rate_limited = auth_fail = not_found = 0
        while True:
            if failed > MAX_FAILED_ATTEMPTS or rate_limited > MAX_RATE_LIMITED or auth_fail > 10:
                raise Fatal(f"giving up on {method} {path}: failed={failed} "
                            f"rate_limited={rate_limited} auth_fail={auth_fail}")
            if auth and self.token is None:
                self.refresh_token("initial")
            tok = self.token if auth else None
            try:
                status, headers, body = self._send(method, path, auth)
            except (urllib.error.URLError, OSError, http.client.HTTPException) as e:
                failed += 1
                self.bump("network_error")
                self.note(method=method, path=path, error=repr(e), token=tok)
                time.sleep(min(2 ** min(failed, 5), 30))
                continue
            try:
                data = json.loads(body)
            except ValueError:
                data = None
            entry = {"method": method, "path": path, "status": status, "token": tok}
            if status != 200:
                entry["body"] = body[:300].decode("utf-8", "replace")
                entry["retry_after_hdr"] = headers.get("Retry-After")
            self.note(**entry)
            self.bump(f"status_{status}")

            if status == 200:
                problem = None
                if not isinstance(data, dict):
                    problem = "body is not a JSON object"
                elif validate is not None:
                    problem = validate(data)
                if problem:
                    failed += 1
                    self.bump("invalid_200")
                    self.note(method=method, path=path, invalid=problem,
                              body=body[:300].decode("utf-8", "replace"))
                    time.sleep(1.0)
                    continue
                if auth:
                    self.token_uses += 1
                return data

            hint = self._wait_hint(headers, data)
            if status == 429:
                rate_limited += 1
                time.sleep((hint if hint is not None else 1.0) + 0.05)
                continue
            if status == 401 and auth:
                auth_fail += 1
                if hint is not None:
                    time.sleep(hint + 0.05)
                self.refresh_token(f"401 {entry.get('body', '')[:80]}")
                continue
            if status == 404 and not_found_ok:
                not_found += 1
                if not_found >= 3:
                    return None
                time.sleep(1.0)
                continue
            # 5xx, unexpected 4xx, etc.: the request failed - repeat it
            failed += 1
            time.sleep(max(hint if hint is not None else 0.0, min(2 ** min(failed, 5), 30)) + 0.05)


REQUIRED_ORDER_KEYS = ("id", "customer_id", "status", "placed_at", "amount_cents")


def validate_page(expected_page):
    def check(d):
        for k in ("page", "total_pages", "items", "next"):
            if k not in d:
                return f"missing key {k!r}"
        if d["page"] != expected_page:
            return f"page {d['page']!r} != requested {expected_page}"
        if not isinstance(d["total_pages"], int) or d["total_pages"] < 1:
            return f"bad total_pages {d['total_pages']!r}"
        if not isinstance(d["items"], list):
            return "items is not a list"
        for i, it in enumerate(d["items"]):
            if not isinstance(it, dict):
                return f"item {i} is not an object"
            missing = [k for k in REQUIRED_ORDER_KEYS if k not in it]
            if missing:
                return f"item {i} missing {missing}"
        if d["next"] is not None and not isinstance(d["next"], str):
            return f"bad next {d['next']!r}"
        return None
    return check


def fetch_orders(outdir):
    c = Client(outdir)
    pages_dir = os.path.join(outdir, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    page, last_page = 1, None
    totals = []
    while True:
        data = c.request("GET", f"/orders?page={page}", validate=validate_page(page))
        with open(os.path.join(pages_dir, f"page_{page:03d}.json"), "w") as f:
            json.dump(data, f)
        totals.append(data["total_pages"])
        print(f"page {page}/{data['total_pages']}: {len(data['items'])} items, next={data['next']!r}",
              flush=True)
        last_page = max(totals)
        if page >= last_page and data["next"] is None:
            break
        if page >= last_page and data["next"] is not None:
            print(f"WARNING: page {page} >= total_pages {last_page} but next={data['next']!r}; continuing",
                  flush=True)
        if page > 500:
            raise Fatal("runaway pagination")
        page += 1
    print("total_pages values seen:", sorted(set(totals)))
    print("request stats:", json.dumps(c.counts, sort_keys=True))


def fetch_customers(outdir, idfile):
    c = Client(outdir)
    cdir = os.path.join(outdir, "customers")
    os.makedirs(cdir, exist_ok=True)
    ids = [line.strip() for line in open(idfile) if line.strip()]
    missing = []
    for n, cid in enumerate(ids, 1):
        path_out = os.path.join(cdir, f"{cid}.json")
        if os.path.exists(path_out):            # cache: never look the same customer up twice
            continue

        def check(d, cid=cid):
            for k in ("id", "name", "region", "tier", "discount_pct"):
                if k not in d:
                    return f"missing key {k!r}"
            if d["id"] != cid:
                return f"id {d['id']!r} != requested {cid!r}"
            return None

        data = c.request("GET", f"/customers/{cid}", validate=check, not_found_ok=True)
        if data is None:
            missing.append(cid)
            data = {"__not_found__": True, "id": cid}
        with open(path_out, "w") as f:
            json.dump(data, f)
        if n % 20 == 0:
            print(f"{n}/{len(ids)} customers", flush=True)
    print("customers not found:", missing)
    print("request stats:", json.dumps(c.counts, sort_keys=True))


if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "orders":
        fetch_orders(sys.argv[2])
    elif mode == "customers":
        fetch_customers(sys.argv[2], sys.argv[3])
    else:
        sys.exit(__doc__)

